package com.ethscalper.cockpit;
import org.junit.Test;import java.nio.file.*;import static org.junit.Assert.*;
public final class V23449CvCoreLegacySuppressionTest {
 @Test public void p02ConfirmationCanQualifyBeforeSuppression(){CvCoreMovementRegistry r=new CvCoreMovementRegistry();CvCoreEngine e=new CvCoreEngine(r);CvCoreMovementRegistry.Episode ep=r.observe("ETHUSDT","SHORT",1);CvCoreEngine.Result result=e.observeLegacy("SHORT","SCALP_CONTINUATION","P02",2,
            CvCoreTestFixtures.snapshot(1900,1900.01,1.2,0,.0002),CvCoreTestFixtures.metrics(0,0,0,.1,0,.0002),CvCoreTestFixtures.common(),1,ep);assertTrue(result.accepted());assertEquals(CvCorePolicy.P02_BALANCED_SHORT,result.route);}
 @Test public void engineNeverBuildsSolPlan(){CvCoreMovementRegistry r=new CvCoreMovementRegistry();CvCoreEngine e=new CvCoreEngine(r);SignalDecision sol=SignalDecision.signal(MarketProfile.sol(),"SHORT","RANGE_FADE",90,1,70,69,71,1,1,"",false,70,71,1);CvCoreEngine.Result result=e.observeRaw(sol,CvCoreTestFixtures.snapshot(1900,1900.01,1.2,0,0),CvCoreTestFixtures.metrics(-1,-1,0,1,0,0),CvCoreTestFixtures.common(),1,r.observe("SOLUSDT","SHORT",1));assertFalse(result.matched());}
 @Test public void serviceSuppressesBothLegacyPathsWithoutComparator()throws Exception{Path root=Paths.get(System.getProperty("user.dir")).toAbsolutePath();Path p=root.resolve("app/src/main/java/com/ethscalper/cockpit/MarketWatchService.java");if(!Files.exists(p))p=root.getParent().resolve("app/src/main/java/com/ethscalper/cockpit/MarketWatchService.java");String s=new String(Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8);assertTrue(s.contains("LEGACY_PUBLIC_SUPPRESSED_BY_CV_CORE_V1"));assertTrue(s.contains("runtime.activePlan=null;runtime.lastSignal=null"));assertFalse(s.contains("LegacyPublic"+"Comparator"));assertFalse(s.contains("notifyMarketPlan(event.plan"));}
}
